From 8fee136cb13335d75ccb927b0a4fe5ce9f37dd55 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:10:58 +0100
Subject: [PATCH] runapplication: run scripts that finish before switching
 activities

Scripts in the activated and deactivated folders of an activity only
start after the switch, so they can't prepare what the activity needs.
Executables in new activating and deactivating folders now run first.

BUG: 393603
---
 src/service/Activities.cpp                    |  2 +
 src/service/Activities.h                      |  9 ++++
 .../runapplication/RunApplicationPlugin.cpp   | 41 +++++++++++++++++++
 .../runapplication/RunApplicationPlugin.h     |  2 +
 4 files changed, 54 insertions(+)

diff --git a/src/service/Activities.cpp b/src/service/Activities.cpp
index 65fbbdcf..a0edfdd3 100644
--- a/src/service/Activities.cpp
+++ b/src/service/Activities.cpp
@@ -126,6 +126,8 @@ bool Activities::Private::setCurrentActivity(const QString &activity)
         }
     }

+    Q_EMIT q->currentActivityAboutToChange(currentActivity, activity);
+
     // Saving the current activity, and notifying
     // clients of the change
     currentActivity = activity;
diff --git a/src/service/Activities.h b/src/service/Activities.h
index d07c5940..5a71f6c1 100644
--- a/src/service/Activities.h
+++ b/src/service/Activities.h
@@ -135,6 +135,15 @@ Q_SIGNALS:
      */
     void CurrentActivityChanged(const QString &activity);

+    /**
+     * This signal is emitted right before the global activity
+     * is changed, from the thread doing the change. It is not
+     * exported on D-Bus.
+     * @param previousActivity id of the current activity
+     * @param activity id of the activity that is going to be current
+     */
+    void currentActivityAboutToChange(const QString &previousActivity, const QString &activity);
+
     /**
      * This signal is emitted when a new activity is created
      * @param activity id of the activity
diff --git a/src/service/plugins/runapplication/RunApplicationPlugin.cpp b/src/service/plugins/runapplication/RunApplicationPlugin.cpp
index 81d763d9..cf00b237 100644
--- a/src/service/plugins/runapplication/RunApplicationPlugin.cpp
+++ b/src/service/plugins/runapplication/RunApplicationPlugin.cpp
@@ -37,6 +37,13 @@ bool RunApplicationPlugin::init(QHash<QString, QObject *> &modules)

     connect(m_activitiesService, SIGNAL(CurrentActivityChanged(QString)), this, SLOT(currentActivityChanged(QString)));

+    // Direct connection, so that the switch waits for the scripts to finish
+    connect(m_activitiesService,
+            SIGNAL(currentActivityAboutToChange(QString, QString)),
+            this,
+            SLOT(currentActivityAboutToChange(QString, QString)),
+            Qt::DirectConnection);
+
     const auto currentActivity = Plugin::retrieve<QString>(m_activitiesService, "CurrentActivity");

     currentActivityChanged(currentActivity);
@@ -50,6 +57,15 @@ QString RunApplicationPlugin::activityDirectory(const QString &activity) const
         + QLatin1Char('/');
 }

+void RunApplicationPlugin::currentActivityAboutToChange(const QString &previousActivity, const QString &activity)
+{
+    if (!previousActivity.isEmpty()) {
+        executeAndWaitIn(activityDirectory(previousActivity) + QStringLiteral("deactivating"));
+    }
+
+    executeAndWaitIn(activityDirectory(activity) + QStringLiteral("activating"));
+}
+
 void RunApplicationPlugin::currentActivityChanged(const QString &activity)
 {
     if (m_currentActivity == activity) {
@@ -90,6 +106,31 @@ void RunApplicationPlugin::executeIn(const QString &path) const
     }
 }

+void RunApplicationPlugin::executeAndWaitIn(const QString &path) const
+{
+    QDir directory(path);
+    const auto fileInfos = directory.entryInfoList(QDir::Files | QDir::Executable);
+    for (const auto &fileInfo : fileInfos) {
+        qCDebug(KAMD_LOG_APPLICATION) << "Running before the activity switch: " << fileInfo.filePath();
+
+        auto process = new QProcess();
+        process->setProgram(fileInfo.filePath());
+        process->setProcessChannelMode(QProcess::ForwardedChannels);
+        connect(process, &QProcess::finished, process, &QObject::deleteLater);
+
+        process->start();
+        if (!process->waitForStarted()) {
+            qCWarning(KAMD_LOG_APPLICATION) << "Could not start" << fileInfo.filePath() << process->errorString();
+            delete process;
+            continue;
+        }
+
+        if (!process->waitForFinished(60000)) {
+            qCWarning(KAMD_LOG_APPLICATION) << "Not waiting any longer for" << fileInfo.filePath();
+        }
+    }
+}
+
 // void RunApplicationPlugin::activityRemoved(const QString &activity)
 // {
 //     // TODO: Clean up the directory
diff --git a/src/service/plugins/runapplication/RunApplicationPlugin.h b/src/service/plugins/runapplication/RunApplicationPlugin.h
index 2036277e..3d57c20f 100644
--- a/src/service/plugins/runapplication/RunApplicationPlugin.h
+++ b/src/service/plugins/runapplication/RunApplicationPlugin.h
@@ -19,11 +19,13 @@ public:
     bool init(QHash<QString, QObject *> &modules) override;

 private Q_SLOTS:
+    void currentActivityAboutToChange(const QString &previousActivity, const QString &activity);
     void currentActivityChanged(const QString &activity);

 private:
     QString activityDirectory(const QString &activity) const;
     void executeIn(const QString &directory) const;
+    void executeAndWaitIn(const QString &directory) const;

     QString m_currentActivity;
     QStringList m_previousActivities;
